/** seaLion team mascot, cropped from the team logo (docs: packages/ui/src/assets/sealion-icon.svg). */
const SEALION_ICON = 'data:image/svg+xml;base64,';

export function BrandMark({ width = 28, height = 28 }: { width?: number; height?: number }) {
  // eslint-disable-next-line @next/next/no-img-element -- static Sites export, tiny inline icon
  return <img src={SEALION_ICON} width={width} height={height} alt="" aria-hidden="true" className="brand-mark" />;
}
